BEGIN;
CREATE TEMP TABLE finance_test_state AS SELECT p.user_id owner_id,p.partner_user_id partner_id,(SELECT id FROM auth.users u WHERE u.id NOT IN(p.user_id,p.partner_user_id) LIMIT 1) stranger_id,gen_random_uuid() account_id,gen_random_uuid() tx_old,gen_random_uuid() tx_new FROM partner_links p WHERE p.status='active' LIMIT 1;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM finance_test_state WHERE stranger_id IS NOT NULL) THEN RAISE EXCEPTION 'Test fixture requires a pair and an unrelated user'; END IF; END $$;
GRANT SELECT ON finance_test_state TO authenticated;
INSERT INTO accounts(id,user_id,name,type,current_balance,currency) SELECT account_id,owner_id,'Household rollback test','checking',100,'USD' FROM finance_test_state;
INSERT INTO transactions(id,user_id,account_id,name,amount,date,category) SELECT tx_old,owner_id,account_id,'Old test',10,current_date-40,'Groceries' FROM finance_test_state UNION ALL SELECT tx_new,owner_id,account_id,'Recent test',10,current_date,'Groceries' FROM finance_test_state;
SET LOCAL ROLE authenticated;
DO $$ DECLARE t record; blocked boolean; BEGIN
 SELECT * INTO t FROM finance_test_state;
 PERFORM set_config('request.jwt.claim.sub',t.partner_id::text,true);
 IF EXISTS(SELECT 1 FROM accounts WHERE id=t.account_id) THEN RAISE EXCEPTION 'Private account leaked to partner'; END IF;
 PERFORM set_config('request.jwt.claim.sub',t.owner_id::text,true);
 PERFORM finance_schedule(ARRAY[t.account_id],current_date+1,60,true,'Test future split');
 IF (SELECT owner_pct FROM finance_allocations WHERE account_id=t.account_id AND effective_from='0001-01-01')<>100 THEN RAISE EXCEPTION 'Historical baseline changed'; END IF;
 blocked:=false; BEGIN PERFORM finance_schedule(ARRAY[t.account_id],current_date-1,50,true,'Past'); EXCEPTION WHEN raise_exception THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Historical schedule accepted'; END IF;
 blocked:=false; BEGIN UPDATE finance_allocations SET owner_pct=20 WHERE account_id=t.account_id; EXCEPTION WHEN insufficient_privilege THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Direct allocation edit accepted'; END IF;
 PERFORM finance_share_account(t.account_id,true,current_date-5,NULL);
 PERFORM set_config('request.jwt.claim.sub',t.partner_id::text,true);
 IF NOT EXISTS(SELECT 1 FROM accounts WHERE id=t.account_id) THEN RAISE EXCEPTION 'Approved account missing'; END IF;
 IF EXISTS(SELECT 1 FROM transactions WHERE id=t.tx_old) OR NOT EXISTS(SELECT 1 FROM transactions WHERE id=t.tx_new) THEN RAISE EXCEPTION 'History date gate failed'; END IF;
 blocked:=false;BEGIN PERFORM finance_schedule(ARRAY[t.account_id],current_date+2,10,true,'Other owner');EXCEPTION WHEN raise_exception THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Partner edited account allocation'; END IF;
 PERFORM set_config('request.jwt.claim.sub',t.stranger_id::text,true);
 IF EXISTS(SELECT 1 FROM accounts WHERE id=t.account_id) OR EXISTS(SELECT 1 FROM transactions WHERE id IN(t.tx_old,t.tx_new)) OR EXISTS(SELECT 1 FROM finance_allocations WHERE account_id=t.account_id) THEN RAISE EXCEPTION 'Unrelated user leakage'; END IF;
 PERFORM set_config('request.jwt.claim.sub',t.owner_id::text,true);
 PERFORM finance_save_budget('Test private','mine','USD',date_trunc('month',current_date)::date,100);
 PERFORM finance_save_budget('Test household','household','USD',date_trunc('month',current_date)::date,200);
 PERFORM set_config('request.jwt.claim.sub',t.partner_id::text,true);
 IF EXISTS(SELECT 1 FROM finance_budget_versions WHERE category='Test private' AND owner_id=t.owner_id) OR NOT EXISTS(SELECT 1 FROM finance_budget_versions WHERE category='Test household' AND owner_id=t.owner_id) THEN RAISE EXCEPTION 'Budget visibility failed'; END IF;
 PERFORM finance_unlink();
 IF EXISTS(SELECT 1 FROM accounts WHERE id=t.account_id) OR EXISTS(SELECT 1 FROM transactions WHERE id=t.tx_new) THEN RAISE EXCEPTION 'Unlink failed to revoke access'; END IF;
 PERFORM set_config('request.jwt.claim.sub',t.owner_id::text,true);
 IF EXISTS(SELECT 1 FROM finance_account_sharing WHERE account_id=t.account_id AND enabled) THEN RAISE EXCEPTION 'Unlink left a reusable access grant'; END IF;
 IF NOT EXISTS(SELECT 1 FROM finance_allocations WHERE account_id=t.account_id AND owner_pct=60) THEN RAISE EXCEPTION 'Unlink erased historical allocation'; END IF;
END $$;
RESET ROLE;
ROLLBACK;
SELECT 'PASS: owner controls, partner history boundary, unrelated isolation, immutable past, budget scopes, unlink revocation. All fixtures rolled back.' AS result;

